inputs.script:
// Scroll the search results as a person would, opening "Show more" on cut posts, until max_posts
// posts of the handle in the window were seen or eight scrolls bring nothing new. The page's own
// SearchTimeline batches are kept by the capture step; the cards seen are left on window for the
// next step, for posts no batch carried. No request of its own.
const clean=v=>String(v==null?'':v).trim();const handle=clean(arg0).replace(/^@+/,'');const since=clean(arg1),until=clean(arg2);const cap=Math.max(1,Math.min(1000,parseInt(clean(arg3),10)||250));const delay=Math.max(800,Math.min(5000,parseInt(clean(arg4),10)||1200));const sleep=ms=>new Promise(r=>setTimeout(r,ms));const norm=s=>String(s||'').replace(/ /g,' ').replace(/\s+/g,' ').trim();const found=new Map();const harvest=()=>{for(const a of document.querySelectorAll("main article[data-testid='tweet'],main article")){const link=a.querySelector("a[href*='/status/'] time")?.closest('a')||a.querySelector("a[href*='/status/']");const m=(link?.getAttribute('href')||'').match(/^\/([^/]+)\/status\/(\d+)/);if(!m||m[1].toLowerCase()!==handle.toLowerCase())continue;const time=a.querySelector('time')?.getAttribute('datetime')||null;if(time){const day=time.slice(0,10);if(day<since||day>=until)continue;}found.set(m[2],{id:m[2],post_url:'https://x.com/'+m[1]+'/status/'+m[2],posted_at:time,dom_text:norm(a.querySelector("[data-testid='tweetText']")?.innerText||'')});if(found.size>=cap)break;}};window.scrollTo(0,0);let stale=0,last=0;for(let i=0;i<200&&found.size<cap&&stale<8;i++){document.querySelectorAll("[data-testid='tweet-text-show-more-link']").forEach(b=>{try{b.click()}catch{}});harvest();stale=found.size===last?stale+1:0;last=found.size;window.scrollBy(0,Math.max(700,Math.round(innerHeight*.85)));await sleep(delay);}harvest();window.__rznExportCards=[...found.values()];return {cards:found.size};

// The account's posts from the SearchTimeline batches the page downloaded (capture_responses):
// whole text, media and conversation ids. A post only its card showed is kept as partial.
const clean=v=>String(v==null?'':v).trim();const handle=clean(arg0).replace(/^@+/,'');const since=clean(arg1),until=clean(arg2);const cap=Math.max(1,Math.min(1000,parseInt(clean(arg3),10)||250));const uniq=a=>[...new Set(a.filter(Boolean))];const norm=s=>String(s||'').replace(/ /g,' ').replace(/\s+/g,' ').trim();
const unwrap=r=>(r&&r.__typename==='TweetWithVisibilityResults'?r.tweet:r);const variant=v=>{const xs=(v||[]).filter(x=>/^video//.test(x.content_type||'')&&x.url).sort((a,b)=>(b.bitrate||0)-(a.bitrate||0));return xs[0]?.url||''};
const inWindow=t=>{if(!t)return true;const day=t.slice(0,10);return day>=since&&day<until};
const byId=new Map();const walk=root=>{const stack=[root];while(stack.length){const x=stack.pop();if(!x||typeof x!=='object')continue;if(Array.isArray(x)){for(const v of x)stack.push(v);continue}
  const t=unwrap(x.tweet_results?.result);
  if(t?.legacy&&t.rest_id&&!x.promotedMetadata&&!t.legacy.retweeted_status_result){const u=t.core?.user_results?.result;const sn=u?.core?.screen_name||u?.legacy?.screen_name||'';if(sn.toLowerCase()===handle.toLowerCase())byId.set(String(t.rest_id),{t,sn})}
  for(const v of Object.values(x))if(v&&typeof v==='object')stack.push(v)}};
for(const r of ((params&&params.captured_responses)||{responses:[]}).responses||[])if(r&&r.status>=200&&r.status<300&&r.json)walk(r.json);
const posts=[];
for(const[id,{t,sn}]of byId){const l=t.legacy||{};const posted=l.created_at?new Date(l.created_at).toISOString():null;if(!inWindow(posted))continue;const media=l.extended_entities?.media||l.entities?.media||[];const article=t.article?.article_results?.result||null;const articleText=norm(article?.plain_text||(article?.content_state?.blocks||[]).map(b=>b.text).join('
')||article?.preview_text||'');
  posts.push({id,post_url:'https://x.com/'+sn+'/status/'+id,posted_at:posted,text:norm(t.note_tweet?.note_tweet_results?.result?.text||l.full_text||''),conversation_id:String(l.conversation_id_str||id),
    image_urls:uniq(media.filter(x=>x.type==='photo').map(x=>x.media_url_https)),video_urls:uniq(media.filter(x=>x.type==='video'||x.type==='animated_gif').map(x=>variant(x.video_info?.variants))),article:article?{title:norm(article.title||''),text:articleText}:null,status:'ok'})}
for(const c of window.__rznExportCards||[])if(!byId.has(c.id))posts.push({id:c.id,post_url:c.post_url,posted_at:c.posted_at,text:c.dom_text,conversation_id:c.id,image_urls:[],video_urls:[],article:null,status:'partial',error:'no captured search batch carried this post; card text only'});
// The newest max_posts, as the search shows them, then oldest first.
posts.sort((a,b)=>String(b.posted_at||'').localeCompare(String(a.posted_at||'')));posts.splice(cap);posts.reverse();
const groups=new Map();for(const p of posts){const k=p.conversation_id||p.id;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(p)}const threads=[...groups.values()].filter(g=>g.length>1).map(g=>({conversation_id:g[0].conversation_id,posts:g}));
const md='# @'+handle+' · '+since+' to '+until+'

'+posts.map((p,i)=>'## '+(i+1)+'. '+(p.posted_at||'')+'

'+(p.article?.title?'### '+p.article.title+'

'+p.article.text+'

':p.text+'

')+'[View on X]('+p.post_url+')'+(p.image_urls.length?'

'+p.image_urls.map(u=>'![]('+u+')').join('

'):'')+(p.video_urls.length?'

Videos:
'+p.video_urls.map(u=>'- '+u).join('
'):'')).join('

---

');
const images=uniq(posts.flatMap(p=>p.image_urls)),videos=uniq(posts.flatMap(p=>p.video_urls));
return {handle,since_date:since,until_date:until,posts_found:posts.length,partial_posts:posts.filter(p=>p.status!=='ok').length,posts,threads,markdown:md,image_urls:images,video_urls:videos,asset_urls:[...images,...videos],search_url:location.href};
